import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import username from 'flarum/common/helpers/username';
export default class FeedbackRejectedNotification extends Notification {
  icon() {
    return 'fas fa-circle-xmark';
  }
  href() {
    const notification = this.attrs.notification;
    const fromUser = notification.fromUser();
    if (!fromUser) return app.route('index');
    return app.route('user.feedbacks', {
      username: fromUser.slug()
    });
  }
  content() {
    const notification = this.attrs.notification;
    const fromUser = notification.fromUser();
    if (!fromUser) return 'Your feedback was rejected';
    return app.translator.trans('huseyinfiliz-traderfeedback.forum.notifications.feedback_rejected_title', {
      username: username(fromUser)
    });
  }
  excerpt() {
    return '';
  }
}
flarum.reg.add('huseyinfiliz-traderfeedback', 'forum/components/FeedbackRejectedNotification', FeedbackRejectedNotification);