import app from 'flarum/forum/app';
export default class FeedbackUserDisplay {
  static getUserInfo(props) {
    let displayName = props.displayName || app.translator.trans('huseyinfiliz-traderfeedback.forum.feedback_item.unknown_user');
    let avatarColor = props.avatarColor || '#888';
    let avatarUrl = props.avatarUrl || null;
    let fromUser = null;

    // Try to get from included users first
    if (props.includedUsers) {
      const userData = props.includedUsers.get(String(props.userId));
      if (userData) {
        displayName = userData.displayName || userData.username || app.translator.trans('huseyinfiliz-traderfeedback.forum.feedback_item.user_id_format', {
          id: props.userId
        });
        avatarUrl = userData.avatarUrl;
      }
    }

    // Try to get from store
    fromUser = app.store.getById('users', String(props.userId));
    if (fromUser) {
      displayName = fromUser.displayName() || displayName;
      avatarColor = fromUser.color() || avatarColor;
      avatarUrl = fromUser.avatarUrl() || avatarUrl;
    }
    return {
      displayName,
      avatarColor,
      avatarUrl,
      fromUser
    };
  }
  static view(props) {
    const {
      displayName,
      avatarColor,
      avatarUrl,
      fromUser
    } = this.getUserInfo(props);

    // Kullanıcı profil linki
    const userProfileLink = fromUser ? app.route('user', {
      username: fromUser.slug()
    }) : null;
    const avatarElement = avatarUrl ? m("img", {
      className: "FeedbackItem-avatar",
      src: avatarUrl,
      alt: displayName
    }) : m("span", {
      className: "FeedbackItem-avatar FeedbackItem-avatar--placeholder",
      style: {
        background: avatarColor
      }
    }, displayName[0]?.toUpperCase() || '?');
    const usernameElement = m("span", {
      className: "FeedbackItem-username"
    }, displayName);

    // Eğer user link varsa, tıklanabilir yap
    if (userProfileLink) {
      return m("div", {
        className: "FeedbackItem-user"
      }, m("a", {
        href: userProfileLink,
        className: "FeedbackItem-userLink"
      }, avatarElement), m("a", {
        href: userProfileLink,
        className: "FeedbackItem-userLink"
      }, usernameElement));
    }

    // User link yoksa normal göster
    return m("div", {
      className: "FeedbackItem-user"
    }, avatarElement, usernameElement);
  }
}
flarum.reg.add('huseyinfiliz-traderfeedback', 'forum/components/TraderFeedback/FeedbackUserDisplay', FeedbackUserDisplay);